Section RKA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x17 x18 x19 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 x5 x6 : word).
  Variables (m0 : amem) (WK tl : Z) (rank : list Z).
  Variable Q : machine_state -> Prop.
  Notation RS := (WK + 52).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis LR : zlen rank = 13.
  Hypothesis RR : Forall (fun v => 0 <= v <= 256) rank.
  Hypothesis HWK : ablk WK (WK + 1492).
  Hypothesis ZW : zshadow m0 WK 1492.
  Hypothesis AWR : appW [(RS, RS + 52)].
  Hypothesis RW : rng RNG WK 1492.
  Hypothesis RWs : rng RNG (shad WK) (nshad (1492 + WK mod 8)).
  Hypothesis RKA0 : u32arr asegs m0 WK (map (Z_to_bv 64) rank).

  Notation ST pc mm nx next x11 x12 x13 x15 x16 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 (Z_to_bv 64 WK) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 (tl + 1 - nx))
             x11 x12 x13 (Z_to_bv 64 next) x15 x16 x17 x18 x19 (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 x27
             x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma rkA_loop : forall f n rs rsw next m1 r (x12 x15 x16 : word),
    rank_start_loop f n next rank rs = Ok r -> Z.of_nat f = tl + 1 - n -> 0 <= n <= tl -> 0 <= next <= 256 * n ->
    zlen rs = 13 -> length rsw = 13%nat -> RK.agreeK n rs rsw ->
    u32arr asegs m1 RS rsw ->
    munch [(RS, RS + 52)] m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 ->
    (forall m2 rsw' next' (y11 y12 y13 y15 y16 : word), RK.agreeK (tl + 1) r rsw' -> length rsw' = 13%nat -> zlen r = 13 ->
       u32arr asegs m2 RS rsw' -> munch [(RS, RS + 52)] m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 ->
       evtF asegs RNG Q (ST 0x806a4 m2 (tl + 1) next' y11 y12 y13 y15 y16)) ->
    evtF asegs RNG Q (ST 0x8063c m1 n next (Z_to_bv 64 (WK + 4 * n)) x12 (Z_to_bv 64 (WK + 4 * n)) x15 x16).
Proof using HTL LR RR HWK ZW AWR RW RWs RKA0.
