(* [comment removed for export] *)
Definition soA_inv (m0 m1 : amem) (WK tl : Z) (ws : list Z) (js : list byte) (rs : list Z) (syms : list (option Z))
    (rsw : list word) : Prop :=
  u32arr asegs m1 (WK + 52) rsw /\ length rsw = 13%nat /\ SO.agree tl rs rsw /\ zlen rs = 13
  /\ u8arr asegs m1 (WK + 980) (BM.omerge js syms) /\ length syms = 256%nat
  /\ bytes_at asegs m1 (WK + 1236) (map (Z_to_bv 8) ws)
  /\ munch [(WK + 52, WK + 104); (WK + 980, WK + 1236)] m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.

Section SOA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x6 x18 x19 x22 x24 x25 x27 x28 x29 x30 x31 : word).
  Variables (m0 : amem) (WK tl nbS : Z) (ws : list Z) (js : list byte).
  Variable Q : machine_state -> Prop.
  Notation RS := (WK + 52).
  Notation SY := (WK + 980).
  Notation HW := (WK + 1236).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HNS : 0 <= nbS <= 256.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : Forall (fun w => 0 <= w <= tl) ws.
  Hypothesis HJS : length js = 256%nat.
  Hypothesis HWK : ablk WK (WK + 1492).
  Hypothesis ZW : zshadow m0 WK 1492.
  Hypothesis AWS : appW [(WK + 52, WK + 104); (WK + 980, WK + 1236)].
  Hypothesis RW : rng RNG WK 1492.
  Hypothesis RWs : rng RNG (shad WK) (nshad (1492 + WK mod 8)).
  Notation INV m1 rs syms rsw := (soA_inv m0 m1 WK tl ws js rs syms rsw).
  Notation ST1 pc mm n x5 x11 x12 x16 x17 x21 x23 x26 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 (Z_to_bv 64 WK) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 n) x11 x12
             (Z_to_bv 64 SY) (Z_to_bv 64 RS) (Z_to_bv 64 HW) x16 x17 x18 x19 (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26
             x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  (* [comment removed for export] *)
  Lemma soA1 : forall f n rs syms rsw m1 r (x5 x11 x12 x16 x17 : word),
