  Lemma soA4 : forall f n rs syms rsw m1 r (x5 x11 x12 x17 : word),
    sort_loop f n ws rs syms = Ok r -> Z.of_nat f = nbS - n -> 0 <= n -> n + 4 <= nbS -> INV m1 rs syms rsw ->
    (forall m2 rs' syms' rsw' (y5 y10 y11 y12 y13 y14 y15 y16 y17 : word), r = (rs', syms') -> INV m2 rs' syms' rsw' ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SPA) gp tp y5 x6 (Z_to_bv 64 WK) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12
